import { useEffect, useState } from 'react'
import { api } from '../api/client.js'

export default function Products() {
  const [products, setProducts] = useState([])
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const controller = new AbortController()
    api.get('/products', { signal: controller.signal })
      .then((res) => setProducts(res.data.data ?? res.data))
      .catch((err) => {
        if (err.name !== 'CanceledError') setError(err.response?.data?.message ?? 'Something went wrong')
      })
      .finally(() => setLoading(false))
    return () => controller.abort()
  }, [])

  if (loading) return <p>Loading...</p>
  if (error) return <p role="alert">{error}</p>
  return <ul>{products.map((p) => <li key={p._id}>{p.name} - Rs {p.price}</li>)}</ul>
}

async function createProduct(data) {
  const res = await fetch('/api/products', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',
    body: JSON.stringify(data),
  })
  const body = await res.json()
  if (!res.ok) throw new Error(body.message ?? 'Request failed')   // fetch does not throw on 4xx/5xx
  return body
}

// ## src/routes/auth.js
import { Router } from 'express'
import { signAccessToken, signRefreshToken, verifyRefreshToken } from '../utils/tokens.js'
import User from '../models/User.js'

const router = Router()
const cookieOptions = {
  httpOnly: true,
  secure: process.env.NODE_ENV === 'production',
  sameSite: process.env.CROSS_SITE === 'true' ? 'none' : 'lax',
  path: '/api/auth',
  maxAge: 7 * 24 * 60 * 60 * 1000,
}

router.post('/login', async (req, res) => {
  const user = await User.findOne({ email: req.body.email }).select('+password')
  if (!user || !(await user.matchPassword(req.body.password))) {
    return res.status(401).json({ message: 'Invalid credentials' })
  }
  res.cookie('refreshToken', signRefreshToken(user), cookieOptions)
  res.json({ accessToken: signAccessToken(user), user: { id: user.id, name: user.name, email: user.email } })
})

router.post('/refresh', async (req, res) => {
  try {
    const { sub } = verifyRefreshToken(req.cookies.refreshToken)
    const user = await User.findById(sub)
    if (!user) throw new Error('no user')
    res.json({ accessToken: signAccessToken(user), user: { id: user.id, name: user.name, email: user.email } })
  } catch {
    res.status(401).json({ message: 'Session expired' })
  }
})

router.post('/logout', (req, res) => {
  res.clearCookie('refreshToken', { ...cookieOptions, maxAge: undefined })
  res.status(204).end()
})

export default router

// ## src/api/client.js
import axios from 'axios'

export const api = axios.create({ baseURL: '/api', withCredentials: true })

let accessToken = null
let refreshPromise = null
export const setAccessToken = (t) => { accessToken = t }

api.interceptors.request.use((config) => {
  if (accessToken) config.headers.Authorization = `Bearer ${accessToken}`
  return config
})

api.interceptors.response.use(
  (res) => res,
  async (error) => {
    const original = error.config
    const isAuthCall = original.url?.includes('/auth/')
    if (error.response?.status === 401 && !original._retried && !isAuthCall) {
      original._retried = true
      refreshPromise ??= api.post('/auth/refresh').finally(() => { refreshPromise = null })
      try {
        const { data } = await refreshPromise
        setAccessToken(data.accessToken)
        original.headers.Authorization = `Bearer ${data.accessToken}`
        return api(original)                           // retry once
      } catch (e) {
        setAccessToken(null)
        window.dispatchEvent(new Event('auth:logout'))
      }
    }
    return Promise.reject(error)
  }
)

// ## src/context/AuthContext.jsx
import { createContext, useContext, useEffect, useState } from 'react'
import { api, setAccessToken } from '../api/client.js'

const AuthContext = createContext(null)
export const useAuth = () => useContext(AuthContext)

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(true)

  // restore session after page reload
  useEffect(() => {
    api.post('/auth/refresh')
      .then(({ data }) => { setAccessToken(data.accessToken); setUser(data.user) })
      .catch(() => setUser(null))
      .finally(() => setLoading(false))
    const onLogout = () => setUser(null)
    window.addEventListener('auth:logout', onLogout)
    return () => window.removeEventListener('auth:logout', onLogout)
  }, [])

  const login = async (email, password) => {
    const { data } = await api.post('/auth/login', { email, password })
    setAccessToken(data.accessToken)
    setUser(data.user)
  }

  const logout = async () => {
    await api.post('/auth/logout')
    setAccessToken(null)
    setUser(null)
  }

  return (
    <AuthContext.Provider value={{ user, loading, login, logout }}>
      {children}
    </AuthContext.Provider>
  )
}

